return {api_version=1,id="OG_254",name="Eater of Secrets",text="<b>Battlecry:</b> Destroy all enemy <b>Secrets</b>. Gain +1/+1 for each.",set="OG",type="minion",rarity="rare",cost=4,attack=2,health=4,keywords={"battlecry"},on_battlecry=function(ctx,self)local secrets=ctx:secrets(ctx:opponent(ctx:controller(self)));for _,s in ipairs(secrets)do ctx:reveal_secret(s)end;if #secrets>0 then ctx:buff(self,#secrets,#secrets)end end}
